import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const k=JSON.parse('{"title":"失物招领与警局领取","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/dialogues/02-lost-property.md","filePath":"zh/more/maltese/practice/dialogues/02-lost-property.md"}'),e={name:"zh/more/maltese/practice/dialogues/02-lost-property.md"},o=r('<h1 id="失物招领与警局领取" tabindex="-1">失物招领与警局领取 <a class="header-anchor" href="#失物招领与警局领取" aria-label="Permalink to &quot;失物招领与警局领取&quot;">​</a></h1><p><strong>场景：</strong> Mark 在警局接听失主 Anna 的电话，两人确认钱包并约定领取时间。</p><h2 id="完整对话" tabindex="-1">完整对话 <a class="header-anchor" href="#完整对话" aria-label="Permalink to &quot;完整对话&quot;">​</a></h2><p><strong>Anna：</strong> Bonġu. Sibtu kartiera mitlufa ħdejn il-waqfa tal-karozzi tal-linja?</p><p><strong>Mark：</strong> Iva, il-kartiera tinsab hawn fl-għassa tal-pulizija.</p><p><strong>Anna：</strong> X&#39;nagħmel biex niġi niġborha?</p><p><strong>Mark：</strong> Tista&#39; tiġi l-għassa għada filgħodu.</p><p><strong>Anna：</strong> Nista&#39; niġi fid-disgħa?</p><p><strong>Mark：</strong> Iva. Ġib miegħek dokument ta&#39; identità.</p><p><strong>Anna：</strong> Se jkolli bżonn inġib xi prova oħra?</p><p><strong>Mark：</strong> Le, id-dokument tal-identità jkun biżżejjed.</p><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><h3 id="_1-anna-失主" tabindex="-1">1. Anna（失主） <a class="header-anchor" href="#_1-anna-失主" aria-label="Permalink to &quot;1. Anna（失主）&quot;">​</a></h3><p><strong>Malti:</strong> Bonġu. Sibtu kartiera mitlufa ħdejn il-waqfa tal-karozzi tal-linja?</p><p><strong>整句：</strong> 你好。您是否在公交车站附近捡到一个丢失的钱包？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Bonġu</td><td>你好</td><td>问候语</td></tr><tr><td>Sibtu</td><td>您找到/捡到了吗</td><td><code>sibt</code>“我/你找到”依语境解释；<code>-u</code> 可指代阳性物件，这里相当于“它”</td></tr><tr><td>kartiera</td><td>钱包</td><td>阴性名词</td></tr><tr><td>mitlufa</td><td>丢失的</td><td>阴性单数形式，与 <code>kartiera</code> 一致</td></tr><tr><td>ħdejn</td><td>在……旁边；附近</td><td>位置介词</td></tr><tr><td>il-waqfa</td><td>车站；停靠点</td><td>阴性名词，带定冠词</td></tr><tr><td>tal-karozzi</td><td>汽车的</td><td><code>ta&#39;</code> 与定冠词缩合；<code>karozzi</code> 为复数</td></tr><tr><td>tal-linja</td><td>线路的</td><td><code>ta&#39; + il-linja</code> 的缩合形式，<code>karozzi tal-linja</code> 指公交车</td></tr></tbody></table><h3 id="_2-mark-警局工作人员" tabindex="-1">2. Mark（警局工作人员） <a class="header-anchor" href="#_2-mark-警局工作人员" aria-label="Permalink to &quot;2. Mark（警局工作人员）&quot;">​</a></h3><p><strong>Malti:</strong> Iva, il-kartiera tinsab hawn fl-għassa tal-pulizija.</p><p><strong>整句：</strong> 是的，钱包在这里的警察局。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Iva</td><td>是的</td><td>肯定回答</td></tr><tr><td>il-kartiera</td><td>钱包</td><td><code>il-</code> 定冠词 + <code>kartiera</code></td></tr><tr><td>tinsab</td><td>位于；在</td><td>阴性主语所用形式</td></tr><tr><td>hawn</td><td>这里</td><td>地点副词</td></tr><tr><td>fl-għassa</td><td>在警局</td><td><code>f&#39;</code>“在” + <code>l-għassa</code> 的缩合形式</td></tr><tr><td>tal-pulizija</td><td>警察的</td><td><code>ta&#39; + il-pulizija</code> 的缩合形式</td></tr></tbody></table><h3 id="_3-anna-失主" tabindex="-1">3. Anna（失主） <a class="header-anchor" href="#_3-anna-失主" aria-label="Permalink to &quot;3. Anna（失主）&quot;">​</a></h3><p><strong>Malti:</strong> X&#39;nagħmel biex niġi niġborha?</p><p><strong>整句：</strong> 我该怎么做才能来把它领走？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>X&#39;</td><td>什么；怎样</td><td><code>x&#39;</code> 是 <code>xiex</code> 的缩写形式</td></tr><tr><td>nagħmel</td><td>我做</td><td>第一人称单数形式</td></tr><tr><td>biex</td><td>为了；以便</td><td>引出目的或后续动作</td></tr><tr><td>niġi</td><td>我来</td><td>第一人称单数形式</td></tr><tr><td>niġborha</td><td>我把它领走/取回</td><td><code>niġbor</code>“我收集/领取” + <code>-ha</code>“它（阴性）”</td></tr></tbody></table><h3 id="_4-mark-警局工作人员" tabindex="-1">4. Mark（警局工作人员） <a class="header-anchor" href="#_4-mark-警局工作人员" aria-label="Permalink to &quot;4. Mark（警局工作人员）&quot;">​</a></h3><p><strong>Malti:</strong> Tista&#39; tiġi l-għassa għada filgħodu.</p><p><strong>整句：</strong> 您明天早上可以来警局。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tista&#39;</td><td>你可以；您可以</td><td>第二人称单数形式</td></tr><tr><td>tiġi</td><td>来</td><td>与 <code>tista&#39;</code> 连用，表示可以来</td></tr><tr><td>l-għassa</td><td>警局；警察岗亭</td><td>阴性名词，带定冠词</td></tr><tr><td>għada</td><td>明天</td><td>时间副词</td></tr><tr><td>filgħodu</td><td>在早上</td><td>时间表达</td></tr></tbody></table><h3 id="_5-anna-失主" tabindex="-1">5. Anna（失主） <a class="header-anchor" href="#_5-anna-失主" aria-label="Permalink to &quot;5. Anna（失主）&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; niġi fid-disgħa?</p><p><strong>整句：</strong> 我可以九点来吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>我可以吗</td><td>第一人称单数形式</td></tr><tr><td>niġi</td><td>我来</td><td>第一人称单数形式</td></tr><tr><td>fid-disgħa</td><td>在九点</td><td><code>f&#39;</code>“在” + <code>id-disgħa</code>“九点”的缩合形式</td></tr></tbody></table><h3 id="_6-mark-警局工作人员" tabindex="-1">6. Mark（警局工作人员） <a class="header-anchor" href="#_6-mark-警局工作人员" aria-label="Permalink to &quot;6. Mark（警局工作人员）&quot;">​</a></h3><p><strong>Malti:</strong> Iva. Ġib miegħek dokument ta&#39; identità.</p><p><strong>整句：</strong> 可以。请随身带上身份证件。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Iva</td><td>是；可以</td><td>肯定回答</td></tr><tr><td>Ġib</td><td>带来；拿来</td><td>对一人的命令式</td></tr><tr><td>miegħek</td><td>和你一起；随身</td><td><code>miegħ</code>“和” + <code>-ek</code>“你”</td></tr><tr><td>dokument</td><td>文件；证件</td><td>阳性名词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接名词，表示所属或类别</td></tr><tr><td>identità</td><td>身份</td><td>阴性名词</td></tr></tbody></table><h3 id="_7-anna-失主" tabindex="-1">7. Anna（失主） <a class="header-anchor" href="#_7-anna-失主" aria-label="Permalink to &quot;7. Anna（失主）&quot;">​</a></h3><p><strong>Malti:</strong> Se jkolli bżonn inġib xi prova oħra?</p><p><strong>整句：</strong> 我还需要带其他证明吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Se</td><td>将；会</td><td>常用将来标记</td></tr><tr><td>jkolli</td><td>我将有；我需要</td><td><code>għandi</code> 的将来形式之一</td></tr><tr><td>bżonn</td><td>需要</td><td><code>ikolli bżonn</code> 表示“我需要”</td></tr><tr><td>inġib</td><td>我带来</td><td>第一人称单数形式</td></tr><tr><td>xi</td><td>一些；任何</td><td>此处表示“其他的/任何”</td></tr><tr><td>prova</td><td>证明；证据</td><td>阴性名词</td></tr><tr><td>oħra</td><td>其他的</td><td>阴性形式，与 <code>prova</code> 一致</td></tr></tbody></table><h3 id="_8-mark-警局工作人员" tabindex="-1">8. Mark（警局工作人员） <a class="header-anchor" href="#_8-mark-警局工作人员" aria-label="Permalink to &quot;8. Mark（警局工作人员）&quot;">​</a></h3><p><strong>Malti:</strong> Le, id-dokument tal-identità jkun biżżejjed.</p><p><strong>整句：</strong> 不用，身份证件就足够了。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Le</td><td>不；不用</td><td>否定回答</td></tr><tr><td>id-dokument</td><td>文件；证件</td><td>定冠词与名词连写</td></tr><tr><td>tal-identità</td><td>身份的</td><td><code>ta&#39; + l-identità</code> 的缩合形式</td></tr><tr><td>jkun</td><td>会是；足以</td><td><code>ikun</code> 的从属/虚拟形式</td></tr><tr><td>biżżejjed</td><td>足够</td><td>固定形容词/副词表达</td></tr></tbody></table><h2 id="词汇补充" tabindex="-1">词汇补充 <a class="header-anchor" href="#词汇补充" aria-label="Permalink to &quot;词汇补充&quot;">​</a></h2><ul><li><code>uffiċċju tal-pulizija</code>：警察局办公室。</li><li><code>rapport</code>：报告；报案记录。</li><li><code>Tlift il-kartiera tiegħi.</code>：我把钱包弄丢了。</li><li>领取失物时，实际手续可能因警局和物品类型而异；对话用于语言练习。</li></ul>',46),i=[o];function n(l,h,s,c,b,p){return d(),a("div",null,i)}const u=t(e,[["render",n]]);export{k as __pageData,u as default};
